def seed_plans_and_preserve_tenants(apps, schema_editor):
    Plan = apps.get_model("core", "SubscriptionPlan")
    Subscription = apps.get_model("core", "BusinessSubscription")
    Event = apps.get_model("core", "SubscriptionEvent")
    Business = apps.get_model("core", "Business")
    db = schema_editor.connection.alias
    features = ["catalog", "pos", "qr_ordering", "inventory", "promotions", "analytics", "payments", "team", "stations"]
    starter, _ = Plan.objects.using(db).get_or_create(
        code="starter-trial",
        defaults={"name": "Veyra Starter Trial", "monthly_price": "0.00", "currency": "IDR", "trial_days": 14, "entitlements": {"features": features, "limits": {}}},
    )
    legacy, _ = Plan.objects.using(db).get_or_create(
        code="legacy-access",
        defaults={"name": "Existing tenant access", "monthly_price": "0.00", "currency": "IDR", "trial_days": 0, "entitlements": {"features": ["*"], "limits": {}}},
    )
    for business in Business.objects.using(db).iterator():
        subscription, created = Subscription.objects.using(db).get_or_create(
            business_id=business.pk,
            defaults={"plan_id": legacy.pk, "status": "grandfathered"},
        )
        if created:
            Event.objects.using(db).create(
                subscription_id=subscription.pk,
                event_type="legacy_access_migrated",
                to_status="grandfathered",
                to_plan=legacy.code,
            )


